    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // 1. Waste ratio and base penalty
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let mut score = waste_ratio * 4.5; // base scaling

    // 2. High‑waste penalty (tighter threshold)
    if waste_ratio > 0.35 {
        let excess = waste_ratio - 0.35;
        score += excess.powi(2) * 120.0;
    }

    // 3. Tight‑fit reward
    if waste_ratio < 0.015 {
        score -= 18.0;
    }

    // 4. Residual variance penalty / reward
    let residual_diff = ((bin_residual as f64) - mean_residual).abs() / bin_capacity as f64;
    score += residual_diff * 1.8;

    // 5. Item size ratio adjustments
    let item_ratio = item_size as f64 / bin_capacity as f64;
    if item_ratio > 0.92 {
        score -= 1.5;
    } else if item_ratio < 0.08 && waste_ratio > 0.55 {
        score += 2.5;
    }

    // 6. Look‑ahead handling
