        let diff = (next_item_size - post_residual) as f64;
        score += diff * 1.2;
    } else {
        score -= 0.9;
        let gap = post_residual.saturating_sub(next_item_size);
        if gap <= 4 {
            score -= 0.8;
        }
    }

    // 7. New‑bin opening penalty
    if bin_residual == bin_capacity {
        let base = ((open_bins_count as f64).ln() + 1.0).powf(1.2);
        score += base * 0.25;
    }

    // 8. Fitting‑bins penalty
    score -= (fitting_bins_count as f64).powf(1.05) * 0.0015;

    // 9. Progress adjustment
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (1.0 - progress) * 0.025;

    // 10. Additional waste thresholds
