        score -= 22.0;
    } else if waste_ratio < 0.03 {
        score -= 9.0;
    } else if waste_ratio < 0.09 {
        score -= 4.0;
    }

    // 11. Final weighting
    score * 0.68 + (post_residual as f64) * 0.32
