    // Encourage residuals close to the current mean
    let mean_diff = ((bin_residual as f64) - mean_residual).abs() / bin_capacity as f64;
    score += mean_diff * 2.5;

    // Handle large items that consume most of a bin
    let item_ratio = item_size as f64 / bin_capacity as f64;
    if item_ratio > 0.92 {
        score -= 1.8;
    } else if item_ratio < 0.15 && waste_ratio > 0.55 {
        score += 2.5;
    }

    // Look‑ahead: compare next item to the residual after placing current item
    if next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        score += diff * 1.6;
    } else {
        score -= 1.0;
        let gap = post_residual.saturating_sub(next_item_size);
        if gap <= 6 {
            score -= 0.8;
        }
    }

    // Penalise opening a brand‑new bin, but adapt to the number of open bins
