    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic waste ratio and baseline score
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let mut score = waste_ratio * 8.0 - (1.0 - waste_ratio) * 6.0;

    // Tight residual bonus / penalty
    if waste_ratio < 0.01 {
        score -= 20.0;
    } else if waste_ratio < 0.04 {
        score -= 8.0;
    } else if waste_ratio < 0.10 {
        score -= 3.0;
    }

    // Excess waste penalty
    if waste_ratio > 0.40 {
        let excess = waste_ratio - 0.40;
        score += excess.powi(2) * 120.0;
    }

    // Deviation from mean residual
    let mean_diff = ((bin_residual as f64) - mean_residual).abs() / bin_capacity as f64;
    score += mean_diff * 2.5;

    // Item size relative to bin
    let item_ratio = item_size as f64 / bin_capacity as f64;
    if item_ratio > 0.95 {
        score -= 1.5;
    } else if item_ratio < 0.15 && waste_ratio > 0.70 {
        score += 2.5;
    }

    // Look‑ahead consideration
    if next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        score += diff * 1.5;
    } else {
        score -= 0.5;
        let gap = post_residual.saturating_sub(next_item_size);
        if gap <= 2 {
            score -= 0.5;
        }
    }

    // Fine‑grained small‑item handling
    if bin_residual < 5 && item_size < 10 {
        score -= 2.0;
    }

    // Avoid filling a bin almost full with a very large item
    if bin_residual > bin_capacity * 9 / 10 && item_size > bin_capacity * 8 / 10 {
        score += 3.0;
    }

    // New bin penalty
    if bin_residual == bin_capacity {
        let penalty = ((open_bins_count as f64).ln() + 1.0).powf(1.4) * 0.25;
        score += penalty;
    }

    // Favor bins that have been used more often
    score -= (fitting_bins_count as f64).powf(1.2) * 0.0008;

    // Progress‑dependent scaling
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (1.0 - progress) * 0.07;

    // Blend with remaining residual
    score = score * 0.75 + (post_residual as f64) * 0.25;

    // Additional deviation penalty
    score += ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64) * 0.5;

    score
}

