    // Base residual ratio after placing the item
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    // Start with a lightweight residual penalty
    let mut score = residual_ratio * 7.5;

    // New bin candidate: penalise heavily if many bins are already open
    if bin_residual == bin_capacity {
        score -= (open_bins_count as f64).powf(0.6) * 2.2;
    }

    // Next‑item fit consideration
    if next_item_size > post_residual {
        let diff = next_item_size - post_residual;
        score += diff as f64 * 0.6;
    } else {
        let waste = post_residual - next_item_size;
        score -= (waste as f64).sqrt() * 0.28;
    }

    // Penalise bins that end up far below mean residual
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.02;

    // Utility based bonus/penalty
    let bin_util = 1.0 - residual_ratio;
    if bin_util < 0.3 {
        // heavily under‑utilised bin
        score += (0.3 - bin_util) * 3.0;
    } else {
        score -= (bin_util - 0.3) * 1.5;
    }

    // Small bonus for many fitting bins
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.03;
    }

    // Open‑bins penalty scaled logarithmically
    score += (open_bins_count as f64).ln().max(0.0) * 0.025;

    // Progress‑dependent scaling: favour early placements
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (1.0 - progress).powi(2) * 0.065;

    // Final blending with raw residual
    score = score * 0.68 + (post_residual as f64) * 0.32;

    score
