pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Residual ratio after placement
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Base score: penalise high residuals more aggressively
    let mut score = residual_ratio * 8.0;

    // New‑bin candidate: discourages opening when many bins are already open
    if bin_residual == bin_capacity {
        score -= (open_bins_count as f64).powf(0.5) * 2.0;
    }

    // Look‑ahead penalty/bonus based on the next item
    if next_item_size > post_residual {
        // Next item will not fit – increase cost
        let diff = next_item_size - post_residual;
        score += diff as f64 * 0.7;
    } else {
        // There is slack – reward by reducing waste
        let waste = post_residual - next_item_size;
        score -= (waste as f64).sqrt() * 0.35;
    }

    // Penalise bins that drift far from the mean residual
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.03;
    // Add a squared‑term to damp large deviations
    score += residual_diff.powi(2) * 0.001;

    // Utility‑based adjustment
    let bin_util = 1.0 - residual_ratio;
    if bin_util < 0.35 {
        // Highly under‑utilised – add a steep penalty
        score += (0.35 - bin_util) * 3.5;
    } else {
        // Moderately utilized – slight reward
        score -= (bin_util - 0.35) * 1.7;
    }

    // Bonus for bins with many alternatives
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.04;
    }

    // Logarithmic penalty for many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.03;

    // Scale by remaining progress – favour tighter packing later
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (1.0 - progress).powi(3) * 0.07;

    // Final blending with raw residual to keep absolute magnitude in check
    score = score * 0.65 + (post_residual as f64) * 0.35;

